INSERT INTO public.question (id, course_id, rubric_id, generation_id, topic, prompt, expected_answer, source_ref, key_points, bloom_level, status, source, author_id, reviewed_by, reviewed_at, created_at, updated_at) VALUES
	('e0000000-0000-0000-0000-000000000002', 'c0000000-0000-0000-0000-000000000001', 'b0000000-0000-0000-0000-000000000001', NULL, 'Architecture styles', 'Compare layered architecture with microservices.', 'Layered is simpler to build and deploy as one unit. Microservices scale and deploy independently but add operational and network complexity.', NULL, 'monolith vs distributed, independent deployment, complexity trade-off', 'ANALYZE', 'APPROVED', 'MANUAL', 'a0000000-0000-0000-0000-000000000002', 'a0000000-0000-0000-0000-000000000002', '2026-10-05 12:18:27.149038+00', '2026-10-05 12:18:27.149038+00', '2026-10-05 12:18:27.149038+00'),
	('e0000000-0000-0000-0000-000000000003', 'c0000000-0000-0000-0000-000000000001', 'b0000000-0000-0000-0000-000000000001', NULL, 'SOLID', 'What does the Dependency Inversion Principle say?', 'High-level modules should not depend on low-level modules. Both should depend on abstractions.', NULL, 'abstractions, high-level vs low-level, decoupling', 'REMEMBER', 'PENDING_REVIEW', 'AI', 'a0000000-0000-0000-0000-000000000002', NULL, NULL, '2026-10-05 12:18:27.149038+00', '2026-10-05 12:18:27.149038+00'),
	('e0000000-0000-0000-0000-000000000004', 'c0000000-0000-0000-0000-000000000002', 'b0000000-0000-0000-0000-000000000002', NULL, 'Normalization', 'Why do we normalize a database to third normal form?', 'To reduce redundancy and avoid update, insert and delete anomalies by removing partial and transitive dependencies.', NULL, 'redundancy, anomalies, transitive dependency', 'UNDERSTAND', 'APPROVED', 'MANUAL', 'a0000000-0000-0000-0000-000000000002', 'a0000000-0000-0000-0000-000000000002', '2026-10-05 12:18:27.149038+00', '2026-10-05 12:18:27.149038+00', '2026-10-05 12:18:27.149038+00'),
	('e0000000-0000-0000-0000-000000000005', 'c0000000-0000-0000-0000-000000000002', 'b0000000-0000-0000-0000-000000000002', NULL, 'SQL', 'When would you choose a LEFT JOIN instead of an INNER JOIN?', 'Use LEFT JOIN when rows from the left table must be kept even without a match in the right table.', NULL, 'keep unmatched rows, null values, reporting', 'APPLY', 'APPROVED', 'IMPORT', 'a0000000-0000-0000-0000-000000000002', 'a0000000-0000-0000-0000-000000000002', '2026-10-05 12:18:27.149038+00', '2026-10-05 12:18:27.149038+00', '2026-10-05 12:18:27.149038+00'),
	('e0000000-0000-0000-0000-000000000006', 'c0000000-0000-0000-0000-000000000001', 'b0000000-0000-0000-0000-000000000001', NULL, 'MVC', 'Trong m├┤ h├¼nh MVC, vai tr├▓ cß╗ºa Controller l├á g├¼?', 'Controller nhß║¡n input tß╗½ ng╞░ß╗¥i d├╣ng, gß╗ìi Model xß╗¡ l├╜ dß╗» liß╗çu v├á chß╗ìn View ─æß╗â hiß╗ân thß╗ï kß║┐t quß║ú.', NULL, '─æiß╗üu phß╗æi luß╗ông, t├ích biß╗çt giao diß╗çn v├á logic', 'REMEMBER', 'APPROVED', 'MANUAL', 'a0000000-0000-0000-0000-000000000002', 'a0000000-0000-0000-0000-000000000002', '2026-10-05 12:18:27.149038+00', '2026-10-05 12:18:27.149038+00', '2026-10-05 12:18:27.149038+00'),
	('e0000000-0000-0000-0000-000000000007', 'c0000000-0000-0000-0000-000000000001', 'b0000000-0000-0000-0000-000000000001', NULL, 'Clean architecture', 'So s├ính Clean Architecture vß╗¢i kiß║┐n tr├║c ph├ón lß╗¢p truyß╗ün thß╗æng khi dß╗▒ ├ín cß║ºn mß╗ƒ rß╗Öng theo domain.', 'Clean Architecture ─æß║╖t business rules ß╗ƒ trung t├óm v├á phß╗Ñ thuß╗Öc h╞░ß╗¢ng v├áo trong; ph├ón lß╗¢p truyß╗ün thß╗æng dß╗à bß╗ï r├áng buß╗Öc chß║╖t giß╗»a UI, service v├á persistence.', NULL, 'dependency rule, domain ß╗ƒ core, ─æß╗òi UI/DB ├¡t ß║únh h╞░ß╗ƒng logic', 'ANALYZE', 'APPROVED', 'MANUAL', 'a0000000-0000-0000-0000-000000000002', 'a0000000-0000-0000-0000-000000000002', '2026-10-05 12:18:27.149038+00', '2026-10-05 12:18:27.149038+00', '2026-10-05 12:18:27.149038+00'),
	('e0000000-0000-0000-0000-000000000008', 'c0000000-0000-0000-0000-000000000001', 'b0000000-0000-0000-0000-000000000001', NULL, 'SOLID', 'Cho v├¡ dß╗Ñ c├ích ├íp dß╗Ñng Open/Closed Principle khi th├¬m loß║íi b├ío c├ío mß╗¢i.', '─Éß╗ïnh ngh─⌐a interface ReportExporter v├á th├¬m implementation mß╗¢i thay v├¼ sß╗¡a class c┼⌐ ─æang xß╗¡ l├╜ nhiß╗üu ─æß╗ïnh dß║íng.', NULL, 'interface, mß╗ƒ rß╗Öng kh├┤ng sß╗¡a code c┼⌐, strategy', 'APPLY', 'PENDING_REVIEW', 'AI', 'a0000000-0000-0000-0000-000000000002', NULL, NULL, '2026-10-05 12:18:27.149038+00', '2026-10-05 12:18:27.149038+00'),
	('e0000000-0000-0000-0000-000000000009', 'c0000000-0000-0000-0000-000000000002', 'b0000000-0000-0000-0000-000000000002', NULL, 'Indexing', 'Khi n├áo n├¬n tß║ío composite index v├á thß╗⌐ tß╗▒ cß╗Öt trong index c├│ ├╜ ngh─⌐a g├¼?', 'D├╣ng composite index khi truy vß║Ñn lß╗ìc/sß║»p xß║┐p theo nhiß╗üu cß╗Öt; cß╗Öt c├│ ─æß╗Ö chß╗ìn lß╗ìc cao hoß║╖c xuß║Ñt hiß╗çn trong WHERE n├¬n ─æß╗⌐ng tr╞░ß╗¢c.', NULL, 'leftmost prefix, selectivity, covering index', 'APPLY', 'APPROVED', 'MANUAL', 'a0000000-0000-0000-0000-000000000002', 'a0000000-0000-0000-0000-000000000002', '2026-10-05 12:18:27.149038+00', '2026-10-05 12:18:27.149038+00', '2026-10-05 12:18:27.149038+00'),
	('e0000000-0000-0000-0000-000000000010', 'c0000000-0000-0000-0000-000000000002', 'b0000000-0000-0000-0000-000000000002', NULL, 'Transactions', 'Giß║úi th├¡ch bß╗æn thuß╗Öc t├¡nh ACID cß╗ºa giao dß╗ïch c╞í sß╗ƒ dß╗» liß╗çu.', 'Atomicity (all-or-nothing), Consistency (r├áng buß╗Öc ─æ╞░ß╗úc giß╗»), Isolation (giao dß╗ïch kh├┤ng thß║Ñy trß║íng th├íi trung gian cß╗ºa nhau), Durability (commit tß╗ôn tß║íi sau sß╗▒ cß╗æ).', NULL, 'atomic, consistent, isolated, durable', 'REMEMBER', 'PENDING_REVIEW', 'IMPORT', 'a0000000-0000-0000-0000-000000000002', '61489f13-bfad-4a5d-8699-2fea4413c52a', '2026-10-06 04:49:05.00482+00', '2026-10-05 12:18:27.149038+00', '2026-10-06 04:49:05.00482+00'),
	('e0000000-0000-0000-0000-000000000001', 'c0000000-0000-0000-0000-000000000001', 'b0000000-0000-0000-0000-000000000001', NULL, 'Design patterns', 'Explain the Singleton pattern and one risk of using it.', 'Singleton ensures a class has a single instance with a global access point. Risks include hidden global state and harder unit testing.', NULL, 'single instance, global access point, hidden state, testing difficulty', 'UNDERSTAND', 'APPROVED', 'MANUAL', 'a0000000-0000-0000-0000-000000000002', 'a0000000-0000-0000-0000-000000000002', '2026-10-06 05:49:16.994211+00', '2026-10-05 12:18:27.149038+00', '2026-10-06 05:49:16.994211+00'),
	('76bbdbeb-ee3f-4ae1-9400-338a9c129dd0', 'c0000000-0000-0000-0000-000000000002', 'b0000000-0000-0000-0000-000000000002', '1c09a07f-fee3-44f9-ba2d-c381a9f0ed65', 'SQL joins', 'What does a SQL JOIN combine rows from?', NULL, 'aives-db.docx, page 1', NULL, 'REMEMBER', 'PENDING_REVIEW', 'AI', 'a0000000-0000-0000-0000-000000000002', NULL, NULL, '2026-10-06 07:56:37.755694+00', '2026-10-06 07:56:37.755694+00'),
	('416063fc-dffe-4b08-8f82-fbad3f389eb0', 'b001316e-4fbd-4d7e-9108-9c27e12675a1', '668e1983-8742-4108-88ae-619bf1e2014f', '16a680f7-1e06-43a6-8891-0d68deb6208d', 'Oral reasoning', 'If a device cannot access the internet, outline the troubleshooting steps you would follow, referencing the definitions of IP configuration, gateway, DNS, and the use of ping.', NULL, '30_networking_questions_answers.docx, page 1', NULL, 'APPLY', 'APPROVED', 'AI', 'eee1ace4-deae-4c16-bf6e-1a36a27b4afd', 'eee1ace4-deae-4c16-bf6e-1a36a27b4afd', '2026-10-06 07:58:34.566622+00', '2026-10-06 07:58:13.384497+00', '2026-10-06 07:58:34.566622+00'),
	('ba401e48-91b8-490e-9a73-0c4a6a62e8cd', 'b001316e-4fbd-4d7e-9108-9c27e12675a1', '668e1983-8742-4108-88ae-619bf1e2014f', '16a680f7-1e06-43a6-8891-0d68deb6208d', 'Oral reasoning', 'Describe the process a browser follows to load a website when you type "example.com" into the address bar, incorporating the definitions of DNS, HTTP/HTTPS, and the steps outlined in the passage.', NULL, '30_networking_questions_answers.docx, page 1', NULL, 'APPLY', 'APPROVED', 'AI', 'eee1ace4-deae-4c16-bf6e-1a36a27b4afd', 'eee1ace4-deae-4c16-bf6e-1a36a27b4afd', '2026-10-06 07:58:34.729026+00', '2026-10-06 07:58:13.379763+00', '2026-10-06 07:58:34.729026+00'),
	('77d1b3ff-c7a6-4778-8b02-13dec3b1f424', 'b001316e-4fbd-4d7e-9108-9c27e12675a1', '668e1983-8742-4108-88ae-619bf1e2014f', '16a680f7-1e06-43a6-8891-0d68deb6208d', 'Oral reasoning', 'A server is configured to listen on port 443. Using the definitions of port numbers and HTTP/HTTPS, explain which protocol is likely being used and why.', NULL, '30_networking_questions_answers.docx, page 1', NULL, 'APPLY', 'APPROVED', 'AI', 'eee1ace4-deae-4c16-bf6e-1a36a27b4afd', 'eee1ace4-deae-4c16-bf6e-1a36a27b4afd', '2026-10-06 07:58:34.868979+00', '2026-10-06 07:58:13.375137+00', '2026-10-06 07:58:34.868979+00'),
	('a6359095-2062-492d-8698-20fe4240977f', 'b001316e-4fbd-4d7e-9108-9c27e12675a1', '668e1983-8742-4108-88ae-619bf1e2014f', '16a680f7-1e06-43a6-8891-0d68deb6208d', 'Oral reasoning', 'Compare and contrast the functions of a hub and a switch, and explain why a switch is typically preferred in modern LANs, based on the passage.', NULL, '30_networking_questions_answers.docx, page 1', NULL, 'APPLY', 'APPROVED', 'AI', 'eee1ace4-deae-4c16-bf6e-1a36a27b4afd', 'eee1ace4-deae-4c16-bf6e-1a36a27b4afd', '2026-10-06 07:58:35.004721+00', '2026-10-06 07:58:13.370188+00', '2026-10-06 07:58:35.004721+00'),
