	('8ec75bfd-c032-4725-9416-6c8317f723d7', 'b001316e-4fbd-4d7e-9108-9c27e12675a1', '668e1983-8742-4108-88ae-619bf1e2014f', '16a680f7-1e06-43a6-8891-0d68deb6208d', 'Oral reasoning', 'If a packet is lost during transmission, describe the steps you would take to troubleshoot the issue, referencing the definitions of packet loss and ping.', NULL, '30_networking_questions_answers.docx, page 1', NULL, 'APPLY', 'APPROVED', 'AI', 'eee1ace4-deae-4c16-bf6e-1a36a27b4afd', 'eee1ace4-deae-4c16-bf6e-1a36a27b4afd', '2026-10-06 07:58:35.320245+00', '2026-10-06 07:58:13.358718+00', '2026-10-06 07:58:35.320245+00'),
	('dd12842e-36a1-43dc-acbd-d6e244bbc6a9', 'b001316e-4fbd-4d7e-9108-9c27e12675a1', '668e1983-8742-4108-88ae-619bf1e2014f', '16a680f7-1e06-43a6-8891-0d68deb6208d', 'Oral reasoning', 'Given a device with IP address 10.0.0.5 and subnet mask 255.0.0.0, determine the network address and the range of host addresses using the definitions of subnet mask and IP address from the passage.', NULL, '30_networking_questions_answers.docx, page 1', NULL, 'APPLY', 'APPROVED', 'AI', 'eee1ace4-deae-4c16-bf6e-1a36a27b4afd', 'eee1ace4-deae-4c16-bf6e-1a36a27b4afd', '2026-10-06 07:58:35.480119+00', '2026-10-06 07:58:13.352471+00', '2026-10-06 07:58:35.480119+00'),
	('924b5365-8e11-4a05-995f-c5acbcd55a87', 'b001316e-4fbd-4d7e-9108-9c27e12675a1', '668e1983-8742-4108-88ae-619bf1e2014f', '16a680f7-1e06-43a6-8891-0d68deb6208d', 'Oral reasoning', 'Explain the difference between TCP and UDP and provide a scenario where each protocol would be the appropriate choice, based on the definitions provided.', NULL, '30_networking_questions_answers.docx, page 1', NULL, 'APPLY', 'APPROVED', 'AI', 'eee1ace4-deae-4c16-bf6e-1a36a27b4afd', 'eee1ace4-deae-4c16-bf6e-1a36a27b4afd', '2026-10-06 07:58:32.519197+00', '2026-10-06 07:58:13.399223+00', '2026-10-06 07:58:32.519197+00'),
	('4c7628c5-036c-459a-8f34-98396a031306', 'b001316e-4fbd-4d7e-9108-9c27e12675a1', '668e1983-8742-4108-88ae-619bf1e2014f', '16a680f7-1e06-43a6-8891-0d68deb6208d', 'Oral reasoning', 'Given a network with high latency, explain how this impacts real-time applications such as VoIP, using the definition of latency.', NULL, '30_networking_questions_answers.docx, page 1', NULL, 'APPLY', 'APPROVED', 'AI', 'eee1ace4-deae-4c16-bf6e-1a36a27b4afd', 'eee1ace4-deae-4c16-bf6e-1a36a27b4afd', '2026-10-06 07:58:34.272471+00', '2026-10-06 07:58:13.393053+00', '2026-10-06 07:58:34.272471+00'),
	('e7e7d28b-1146-48fd-a145-bd8dbc6779cb', 'b001316e-4fbd-4d7e-9108-9c27e12675a1', '668e1983-8742-4108-88ae-619bf1e2014f', '16a680f7-1e06-43a6-8891-0d68deb6208d', 'Oral reasoning', 'Explain how NAT allows multiple devices in a private network to share a single public IP address, using the definition of NAT from the passage.', NULL, '30_networking_questions_answers.docx, page 1', NULL, 'APPLY', 'APPROVED', 'AI', 'eee1ace4-deae-4c16-bf6e-1a36a27b4afd', 'eee1ace4-deae-4c16-bf6e-1a36a27b4afd', '2026-10-06 07:58:34.427185+00', '2026-10-06 07:58:13.388795+00', '2026-10-06 07:58:34.427185+00'),
	('1d3aad37-036d-459f-b7d0-82b59a76be52', '4ec21e82-592f-4cba-b40f-2e02d797f3cc', '2d02d915-56b9-4cd2-afa5-249e25ac9cac', '87f26bca-33aa-4689-8d13-ed742e816c32', 'Oral reasoning', 'Compare the WHERE and HAVING clauses in SQL with respect to when they are applied during query execution and the types of functions they can contain.', 'WHERE filters individual rows before any GROUP BY operation and cannot contain aggregate functions such as SUM, AVG, COUNT, MAX, MIN. HAVING filters groups after the GROUP BY has been performed and is typically used with aggregate functions.', '10_Cau_Hoi_Va_Dap_An_Database.docx, page 1', 'WHERE filters rows before GROUP BY; WHERE cannot contain aggregate functions; HAVING filters groups after GROUP BY; HAVING often contains aggregate functions', 'ANALYZE', 'APPROVED', 'AI', 'eee1ace4-deae-4c16-bf6e-1a36a27b4afd', 'eee1ace4-deae-4c16-bf6e-1a36a27b4afd', '2026-10-06 08:35:59.246716+00', '2026-10-06 08:35:33.429355+00', '2026-10-06 08:35:59.246716+00'),
	('e8d8147f-4de1-4dd4-b67e-e17e49bbef36', '4ec21e82-592f-4cba-b40f-2e02d797f3cc', '2d02d915-56b9-4cd2-afa5-249e25ac9cac', '87f26bca-33aa-4689-8d13-ed742e816c32', 'Oral reasoning', 'Analyze the tradeΓÇæoffs of creating an index on a table: explain the performance benefits for read operations and the penalties for write operations.', 'An index (usually BΓÇæTree or Hash) speeds up data retrieval for WHERE, JOIN, and ORDER BY clauses by avoiding full table scans. However, it consumes extra disk/memory space and slows down INSERT, UPDATE, and DELETE operations because the index structure must be updated on each write.', '10_Cau_Hoi_Va_Dap_An_Database.docx, page 1', 'Index speeds up SELECT/WHERE/JOIN/ORDER BY; Index avoids full table scan; Index consumes extra storage; Index slows INSERT/UPDATE/DELETE due to maintenance', 'ANALYZE', 'APPROVED', 'AI', 'eee1ace4-deae-4c16-bf6e-1a36a27b4afd', 'eee1ace4-deae-4c16-bf6e-1a36a27b4afd', '2026-10-06 08:36:00.768478+00', '2026-10-06 08:35:33.439535+00', '2026-10-06 08:36:00.768478+00'),
	('863111f9-5339-458b-a8bc-2ff263b24c28', '4ec21e82-592f-4cba-b40f-2e02d797f3cc', '2d02d915-56b9-4cd2-afa5-249e25ac9cac', '87f26bca-33aa-4689-8d13-ed742e816c32', 'Oral reasoning', 'A table uses a composite primary key. Explain why achieving Second Normal Form (2NF) is necessary and describe the specific anomaly it eliminates.', '2NF requires the table to be in 1NF and that every nonΓÇækey attribute be fully functionally dependent on the entire primary key, not just part of it. This removes partial dependency anomalies where a nonΓÇækey attribute depends on only a portion of the composite key, leading to redundancy and update anomalies.', '10_Cau_Hoi_Va_Dap_An_Database.docx, page 1', '2NF requires 1NF; nonΓÇækey attributes must depend on whole primary key; eliminates partial dependency; prevents redundancy and update anomalies', 'ANALYZE', 'APPROVED', 'AI', 'eee1ace4-deae-4c16-bf6e-1a36a27b4afd', 'eee1ace4-deae-4c16-bf6e-1a36a27b4afd', '2026-10-06 08:36:02.052424+00', '2026-10-06 08:35:33.447562+00', '2026-10-06 08:36:02.052424+00'),
	('b3ff5603-c428-4dfe-8bf2-01789c80f6ba', '4ec21e82-592f-4cba-b40f-2e02d797f3cc', '2d02d915-56b9-4cd2-afa5-249e25ac9cac', '87f26bca-33aa-4689-8d13-ed742e816c32', 'Oral reasoning', 'Contrast the scaling approaches of relational (SQL) and nonΓÇærelational (NoSQL) databases and relate these approaches to their typical ACID compliance.', 'Relational databases use a fixed schema, enforce strong ACID properties, and scale vertically by adding more powerful hardware. NoSQL databases use flexible schemas (document, keyΓÇævalue, graph, wideΓÇæcolumn), often relax strict ACID for higher performance, and scale horizontally by adding more nodes.', '10_Cau_Hoi_Va_Dap_An_Database.docx, page 1', 'SQL: fixed schema, strong ACID, vertical scaling; NoSQL: flexible schema, relaxed ACID, horizontal scaling; SQL examples: MySQL, Oracle, SQL Server; NoSQL examples: MongoDB, Redis, Cassandra, Neo4j', 'ANALYZE', 'APPROVED', 'AI', 'eee1ace4-deae-4c16-bf6e-1a36a27b4afd', 'eee1ace4-deae-4c16-bf6e-1a36a27b4afd', '2026-10-06 08:36:03.563347+00', '2026-10-06 08:35:33.453743+00', '2026-10-06 08:36:03.563347+00'),
	('ff89ae4c-6007-437a-aca7-4264971b8f27', '4ec21e82-592f-4cba-b40f-2e02d797f3cc', '2d02d915-56b9-4cd2-afa5-249e25ac9cac', '87f26bca-33aa-4689-8d13-ed742e816c32', 'Oral reasoning', 'A fundsΓÇætransfer transaction debits one account and credits another. Describe how each ACID property (Atomicity, Consistency, Isolation, Durability) protects the database if a crash occurs after the debit but before the credit.', 'Atomicity ensures the whole transfer either completes fully or is rolled back, so the debit alone cannot persist. Consistency guarantees the database moves from one valid state (balanced accounts) to another. Isolation prevents other concurrent transactions from seeing the intermediate debitΓÇæonly state. Durability ensures that once the transaction commits, both debit and credit survive any subsequent system failure.', '10_Cau_Hoi_Va_Dap_An_Database.docx, page 1', 'Atomicity: allΓÇæorΓÇænothing; Consistency: valid state to valid state; Isolation: concurrent transactions do not interfere; Durability: committed data persists after crash', 'ANALYZE', 'APPROVED', 'AI', 'eee1ace4-deae-4c16-bf6e-1a36a27b4afd', 'eee1ace4-deae-4c16-bf6e-1a36a27b4afd', '2026-10-06 08:36:05.870397+00', '2026-10-06 08:35:33.460373+00', '2026-10-06 08:36:05.870397+00');
INSERT INTO public.question_turn (id, attempt_id, question_id, parent_turn_id, turn_no, turn_type, follow_up_no, question_text, asked_at) VALUES
	('91000000-0000-0000-0000-000000000001', '90000000-0000-0000-0000-000000000001', 'e0000000-0000-0000-0000-000000000001', NULL, 1, 'MAIN', NULL, 'Explain the Singleton pattern and one risk of using it.', '2026-10-05 12:18:27.163177+00'),
	('91000000-0000-0000-0000-000000000002', '90000000-0000-0000-0000-000000000001', 'e0000000-0000-0000-0000-000000000001', '91000000-0000-0000-0000-000000000001', 2, 'FOLLOW_UP', 1, 'How would you make a Singleton easier to test?', '2026-10-05 12:18:27.163177+00');
INSERT INTO public.answer (id, turn_id, status, transcript, stt_confidence, duration_ms, needs_follow_up, follow_up_reason, stt_latency_ms, llm_latency_ms, answered_at) VALUES
	('92000000-0000-0000-0000-000000000001', '91000000-0000-0000-0000-000000000001', 'ANSWERED', 'Singleton keeps only one instance of a class and gives a global access point. The risk is that it hides global state.', 0.940, 21000, true, 'MISSING_POINT', NULL, NULL, '2026-10-05 12:18:27.167072+00'),
	('92000000-0000-0000-0000-000000000002', '91000000-0000-0000-0000-000000000002', 'ANSWERED', 'I would inject the instance through an interface so a test can replace it with a fake.', 0.910, 14000, false, NULL, NULL, NULL, '2026-10-05 12:18:27.167072+00');
